def _seo_md_to_html(md: str) -> str:
    """Yeni SEO sayfaları için minimal markdown -> html dönüştürücü."""
    import re  # _satir_ici + liste ayracı re.split; dalga bazlı import yoktu (latent)

    def _satir_ici(t):
        """Satır içi **x** -> <strong>x</strong>; eşleşmeyen tek `**` olduğu gibi kalır."""
        return re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", t)

    lines = md.splitlines()
    out = []
    in_ul = False
    para = []

    def _flush_para():
        if para:
            text = _satir_ici(" ".join(para).strip())
            if text:
                out.append(f"<p>{text}</p>")
            para.clear()

    for raw in lines:
        line = raw.strip()

        if not line:
            _flush_para()
            continue

        if line.startswith("# "):
            _flush_para()
            if in_ul:
                out.append("</ul>")
                in_ul = False
            out.append(f"<h1>{_satir_ici(line[2:].strip())}</h1>")
            continue

        if line.startswith("## "):
            _flush_para()
            if in_ul:
                out.append("</ul>")
                in_ul = False
            out.append(f"<h2>{_satir_ici(line[3:].strip())}</h2>")
            continue

        if line.startswith("- "):
            if para:
                _flush_para()
            if not in_ul:
                out.append("<ul>")
                in_ul = True
            rest = line[2:].strip()
            items = [item.strip() for item in re.split(r"\s-\s", rest) if item.strip()]
            if not items:
                items = [rest]
            for item in items:
                out.append(f"<li>{_satir_ici(item)}</li>")
            continue

        if in_ul:
            out.append("</ul>")
            in_ul = False

        para.append(line)

    _flush_para()
    if in_ul:
        out.append("</ul>")

    return "\n".join(out)


